mapper.select:
SELECT c.id, c.activity_id as activityId, c.user_id as userId, vu.real_name as userName, vu.phone as userPhone, c.checkin_time as checkinTime, c.checkout_time as checkoutTime, c.checkin_location as checkinLocation, c.checkout_location as checkoutLocation, c.actual_service_hours as serviceHours, c.status, c.remark, a.title as activityTitle, a.start_time as activityStartTime, a.end_time as activityEndTime, c.created_time as createdTime, c.updated_time as updatedTime FROM activity_checkin c LEFT JOIN volunteer_user vu ON c.user_id = vu.id LEFT JOIN activity a ON c.activity_id = a.id WHERE c.deleted = 0
AND c.activity_id = #{activityId}
AND c.status = #{status}
AND ( vu.real_name LIKE CONCAT('%', #{keyword}, '%') OR vu.phone LIKE CONCAT('%', #{keyword}, '%') OR a.title LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY c.id DESC
